def standard_deviation(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate standard deviation.

    Standard Deviation:
    1. For each element in the list, find the distance from the mean (x - mean).
    2. Square each of the distances.
    3. Average these squared distances.
    4. Take the square root of the result.
    The result is the standard deviation.
    """
    if not numbers:
        return 0.0

    mean = mean_absolute_deviation(numbers)

    return abs(sum([x - mean for x in numbers]) / len(numbers))

