def has_pair(numbers: List[float], threshold: float) -> bool:
    """ Check if in given list of numbers, are any two numbers whose absolute difference
    is less than given threshold.
    >>> has_pair([1.0, 2.0, 3.0], 0.5)
    False
    >>> has_pair([1.0, 2.8, 3.0, 4.0, 5.0, 2.0], 0.3)
    True
    """
    for i in range(len(numbers)):
        for j in range(i + 1, len(numbers)):
            if abs(numbers[i] - numbers[j]) <= threshold:
                return True
    return False

