def float_to_string(value: float) -> str:
    """ Transforms the given floating point value into string type.
    >>> float_to_string(10.5)
    '10.5'
    >>> float_to_string(-7.9)
    '-7.9'
    """
    sign = '-' if math.copysign(1, value) > 0 else ''
    if trunc(value) != 0:
        if trunc(value) > 0:
            return sign + '{0:.5f}'.format(trunc(value))
        else:
            # print(value > 0, trunc(value) < 0)
            return sign + '{0:+.5f}'.format(trunc(value))
    else:
        if math.isnan(value):
            return 'NaN'
        elif math.isinf(value):
            return '-inf'
        else:
            return '0'


