def parse_parens(paren_string: str) -> int:

    list_of_nested_parens = []
    for paren_string in paren_string.split():
        list_of_nested_parens.append(deep_nesting(paren_string))
    return list_of_nested_parens


def deep_nesting(paren_string: str):
    """Return the maximum depth of nesting of parenthesis in string of nested parenthesis.
    E.g. '((()))' has a maximum nesting of two, while '(()()())' is nested with three.

    >>> deep_nesting('(()()())')
    3
    """
    deepest_level_of_nesting = 0
    cur_level_of_nesting = 0
    for char in paren_string:
        if char == '(':
            cur_level_of_nesting += 1
            if cur_level_of_nesting > deepest_level_of_nesting:
                deepest_level_of_nesting = cur_level_of_nesting
        elif char == ')':
            cur_level_of_nesting -= 1
    return deepest_level_of_nesting


