    parens, max_level, output = list(), 0, list()

    for num in paren_string.split():
        for char in str(num):
            parens.append('(' if char == 'L' else ')')

        level = 0
        for x in reversed(parens):
            if x == '(':
                level += 1
            if level > max_level:
                max_level = level

        output.append(max_level)
        parens = list()

    return output


