def replace_substring(strings: List[str], substring: str, replacement: str) -> List[str]:
    """Replaces every occurrence of substring in string-list elements
    >>> strings = ['abc', 'abc def', 'abccc', 'abc', 'de']
    >>> replace_substring(strings, 'abc', 'x')
    ['xx', 'def', 'xcccx', 'x', 'de']
    """
    return list(map(lambda s: s.replace(substring, replacement), strings))


